  @override
  String get ssriMilestone14Title => '两周：身体症状消退';

  @override
  String get ssriMilestone14Description =>
      '大多数急性身体停药症状已显著减少或消退。脑闪、恶心和头晕正在消失。随着大脑继续重新平衡血清素系统，情绪敏感性可能仍然较高。';

  @override
