      '停用TCA后可能出现真实的停药症状，中枢胆碱能过度活动是提出的机制之一。恶心、腹泻、腹痛、失眠、焦虑、躁动和头痛可能较早出现，尤其是在突然停药或减量过快后。第3天是一个里程碑；症状出现的时间和强度因人而异。';

  @override
