  @override
  String get tcaMilestone7Description =>
      '抗抑郁药停药症状通常在几天内开始，并常持续数周。一周后，恶心、出汗、睡眠问题、心悸和头晕仍可能存在。七天是真正的进步，恢复可以继续按不同节奏推进。';

  @override
