  @override
  String get maoiMilestone3Title => '第3天：最高风险阶段 — 必须医疗监督';

  @override
  String get maoiMilestone3Description =>
      'MAOI是所有抗抑郁药类别中停药风险最严重的。突然停药，尤其是苯乙肼和反苯环丙胺，可能导致严重激越、意识混乱、幻觉、肌阵挛和高热。如果出现这些症状，请立即就医。MAOI通过不可逆地使MAO酶失活发挥作用；恢复需要身体合成新的酶，这一过程大约需要14天。';

  @override
  String get maoiMilestone7Title => '一周：MAO酶合成进行中';

  @override
  String get maoiMilestone7Description =>
      'MAOI会不可逆地使MAO酶分子失活；恢复需要合成全新的酶。到一周时，约50%的正常MAO活性可能已经恢复。严重的急性停药症状（谵妄、肌阵挛、高热）已大幅减轻。仍然需要密切的医疗监督。';

  @override
  String get maoiMilestone14Title => '两周：MAO酶活性基本恢复';

  @override
  String get maoiMilestone14Description =>
      '两周是不可逆MAOI停药后MAO酶恢复的标准临床时间框架。MAO-A和MAO-B活性已大幅恢复，正常酪胺代谢已重新建立。可在医师指导下放宽MAOI治疗期间所需的饮食限制。';

  @override
  String get maoiMilestone30Title => '一个月：大脑化学系统重新平衡';

  @override
  String get maoiMilestone30Description =>
      '停用MAOI一个月后，MAO酶再次活跃，大脑会自然处理血清素、去甲肾上腺素、多巴胺和酪胺。特殊的食物和药物相互作用期已经结束，不过仍应告知开药医生您曾使用过MAOI。';

  @override
  String get maoiMilestone90Title => '三个月：大脑化学物质正常化';

  @override
  String get maoiMilestone90Description =>
      '三个月给了大脑的情绪和能量系统充分时间在停用MAOI后重新调整。随着大脑重新自然处理这些化学物质，情绪、精力和清晰思维也在稳定下来。';

  @override
  String get maoiMilestone180Title => '六个月：长期恢复';

  @override
  String get maoiMilestone180Description =>
      '六个月代表了自然单胺功能持续相当长的一段时间。血清素、去甲肾上腺素和多巴胺受体群已恢复正常。受MAOI影响的苯乙胺（PEA）通路也已恢复到自然水平——这是恢复过程中常被忽视的一面，却有助于情绪恢复正常。';

  @override
